import java.time.Duration;
import java.util.Collections;

public class MyConsumer {

    private final KafkaConsumer<String, String> consumer;

    public MyConsumer(String bootstrapServers, String groupId, String topic) {
        consumer = new KafkaConsumer<>(PropertiesUtil.getConsumerProperties(groupId));
        consumer.subscribe(Collections.singletonList(topic));
    }

    public void consumeMessages() {
        Runtime.getRuntime().addShutdownHook(new Thread(this::handleShutdown));

