    }

    private void handleShutdown() {
        System.out.println("Received shutdown signal, pausing consumption...");
        for (TopicPartition partition : consumer.assignment()) {
            consumer.pause(partition);
        }
        System.out.println("Consumption paused.");
        // Additional cleanup or logging if needed
    }

    public static void main(String[] args) {
        MyConsumer consumer = new MyConsumer("kafka_broker:9092", "your_group_id", "your_topic");
        consumer.consumeMessages();
    }
}
